ray( CASE WHEN typeof(ca.submission_id)='blob' THEN json_object('$sqliteBlob',hex(ca.submission_id)) ELSE ca.submission_id END ),'revision',(SELECT MAX(v.revision) FROM file_shadow_dependency_versions v WHERE v.dependency_kind='comment_submission_acceptances' AND v.dependency_key=json_array( CASE WHEN typeof(ca.submission_id)='blob' THEN json_object('$sqliteBlob',hex(ca.submission_id)) ELSE ca.submission_id END ))) FROM comment_submission_acceptances ca WHERE ca.submission_id=x.submission_id)),'gc',json((SELECT json_group_array(json(value)) FROM(SELECT json_object('dependency_key',json_array( CASE WHEN typeof(bg.store_kind)='blob' THEN json_object('$sqliteBlob',hex(bg.store_kind)) ELSE bg.store_kind END , CASE WHEN typeof(bg.provider)='blob' THEN json_object('$sqliteBlob',hex(bg.provider)) ELSE bg.provider END , CASE WHEN typeof(bg.object_key)='blob' THEN json_object('$sqliteBlob',hex(bg.object_key)) ELSE bg.object_key END ),'revision',(SELECT MAX(v.revision) FROM file_shadow_dependency_versions v WHERE v.dependency_kind='blob_gc_ledger' AND v.dependency_key=json_array( CASE WHEN typeof(bg.store_kind)='blob' THEN json_object('$sqliteBlob',hex(bg.store_kind)) ELSE bg.store_kind END , CASE WHEN typeof(bg.provider)='blob' THEN json_object('$sqliteBlob',hex(bg.provider)) ELSE bg.provider END , CASE WHEN typeof(bg.object_key)='blob' THEN json_object('$sqliteBlob',hex(bg.object_key)) ELSE bg.object_key END ))) value FROM blob_gc_ledger bg WHERE (bg.store_kind='r2' AND bg.provider='r2' AND bg.object_key=(a.r2_key)) OR(bg.store_kind='managed' AND bg.provider=(m.provider) AND bg.object_key=(m.object_key)) ORDER BY bg.store_kind,bg.provider,bg.object_key))),'quarantine',json((SELECT json_group_array(json(value)) FROM(SELECT json_object('dependency_key',json_array( CASE WHEN typeof(bq.store_kind)='blob' THEN json_object('$sqliteBlob',hex(bq.store_kind)) ELSE bq.store_kind END , CASE WHEN typeof(bq.provider)='blob' THEN json_object('$sqliteBlob',hex(bq.provider)) ELSE bq.provid