id)='blob' THEN json_object('$sqliteBlob',hex(ar.id)) ELSE ar.id END ))) FROM assets ar WHERE ar.id=x.derived_asset_id)),'ownerImport',json((SELECT json_object('dependency_key',json_array( CASE WHEN typeof(io.id)='blob' THEN json_object('$sqliteBlob',hex(io.id)) ELSE io.id END ),'revision',(SELECT MAX(v.revision) FROM file_shadow_dependency_versions v WHERE v.dependency_kind='imports' AND v.dependency_key=json_array( CASE WHEN typeof(io.id)='blob' THEN json_object('$sqliteBlob',hex(io.id)) ELSE io.id END ))) FROM imports io WHERE io.id=(SELECT import_id FROM assets WHERE r2_key=(a.r2_key)))),'uploadReceipts',json((SELECT json_group_array(json(value)) FROM(SELECT json_object('dependency_key',json_array( CASE WHEN typeof(ur.id)='blob' THEN json_object('$sqliteBlob',hex(ur.id)) ELSE ur.id END ),'revision',(SELECT MAX(v.revision) FROM file_shadow_dependency_versions v WHERE v.dependency_kind='r2_upload_requests' AND v.dependency_key=json_array( CASE WHEN typeof(ur.id)='blob' THEN json_object('$sqliteBlob',hex(ur.id)) ELSE ur.id END ))) value FROM r2_upload_requests ur WHERE ur.candidate_object_key=(a.r2_key) OR CASE WHEN json_valid(ur.accepted_result_json) THEN json_extract(ur.accepted_result_json,'$.key') END =(a.r2_key) ORDER BY ur.id))),'metrologyReceipts',json((SELECT json_group_array(json(value)) FROM(SELECT json_object('dependency_key',json_array( CASE WHEN typeof(ur.id)='blob' THEN json_object('$sqliteBlob',hex(ur.id)) ELSE ur.id END ),'revision',(SELECT MAX(v.revision) FROM file_shadow_dependency_versions v WHERE v.dependency_kind='metrology_reference_upload_requests' AND v.dependency_key=json_array( CASE WHEN typeof(ur.id)='blob' THEN json_object('$sqliteBlob',hex(ur.id)) ELSE ur.id END ))) value FROM metrology_reference_upload_requests ur WHERE ur.candidate_object_key=(a.r2_key) OR CASE WHEN json_valid(ur.accepted_result_json) THEN json_extract(ur.accepted_result_json,'$.reference.assetKey') END =(a.r2_key) ORDER BY ur.id))),'commentReceipts',json((SELECT json