ypeof(bq.store_kind)='blob' THEN json_object('$sqliteBlob',hex(bq.store_kind)) ELSE bq.store_kind END , CASE WHEN typeof(bq.provider)='blob' THEN json_object('$sqliteBlob',hex(bq.provider)) ELSE bq.provider END , CASE WHEN typeof(bq.object_key)='blob' THEN json_object('$sqliteBlob',hex(bq.object_key)) ELSE bq.object_key END ),'revision',(SELECT MAX(v.revision) FROM file_shadow_dependency_versions v WHERE v.dependency_kind='blob_integrity_quarantine' AND v.dependency_key=json_array( CASE WHEN typeof(bq.store_kind)='blob' THEN json_object('$sqliteBlob',hex(bq.store_kind)) ELSE bq.store_kind END , CASE WHEN typeof(bq.provider)='blob' THEN json_object('$sqliteBlob',hex(bq.provider)) ELSE bq.provider END , CASE WHEN typeof(bq.object_key)='blob' THEN json_object('$sqliteBlob',hex(bq.object_key)) ELSE bq.object_key END ))) value FROM blob_integrity_quarantine bq WHERE (bq.store_kind='r2' AND bq.provider='r2' AND bq.object_key=(a.r2_key)) OR(bq.store_kind='managed' AND bq.provider=(NULL) AND bq.object_key=(NULL)) ORDER BY bq.store_kind,bq.provider,bq.object_key))),'mappings',json((SELECT json_group_array(json(value)) FROM(SELECT json_object('dependency_key',json_array( CASE WHEN typeof(lm.store_kind)='blob' THEN json_object('$sqliteBlob',hex(lm.store_kind)) ELSE lm.store_kind END , CASE WHEN typeof(lm.provider)='blob' THEN json_object('$sqliteBlob',hex(lm.provider)) ELSE lm.provider END , CASE WHEN typeof(lm.object_key)='blob' THEN json_object('$sqliteBlob',hex(lm.object_key)) ELSE lm.object_key END ),'revision',(SELECT MAX(v.revision) FROM file_shadow_dependency_versions v WHERE v.dependency_kind='legacy_file_mappings' AND v.dependency_key=json_array( CASE WHEN typeof(lm.store_kind)='blob' THEN json_object('$sqliteBlob',hex(lm.store_kind)) ELSE lm.store_kind END , CASE WHEN typeof(lm.provider)='blob' THEN json_object('$sqliteBlob',hex(lm.provider)) ELSE lm.provider END , CASE WHEN typeof(lm.object_key)='blob' THEN json_object('$sqliteBlob',hex(lm.object_key)) ELSE lm.object_key END ))) value FROM legacy_file_mappings lm WHERE (lm.store_kind='r2' AND lm.provider='r2' AND lm.object_key=(a.r2_key)) OR(lm.store_kind='managed' AND lm.provider=(NULL) AND lm.object_key=(NULL)) ORDER BY lm.store_kind,lm.provider,lm.object_key))),'profileRevision',json((SELECT count(*) FROM file_shadow_dependency_versions WHERE dependency_kind IN('storage_profiles','storage_profile_runtime')))))) source_json,
