CREATE VIEW file_shadow_sources_relational AS SELECT * FROM file_shadow_sources_state_representation_asset_primary UNION ALL SELECT * FROM file_shadow_sources_run_step_asset_primary UNION ALL SELECT * FROM file_shadow_sources_metrology_template_reference_primary UNION ALL SELECT * FROM file_shadow_sources_run_step_comment_primary UNION ALL SELECT * FROM file_shadow_sources_state_verification_evidence;

CREATE VIEW file_shadow_sources_content AS SELECT * FROM file_shadow_sources_comment_submission_item_primary UNION ALL SELECT * FROM file_shadow_sources_project_content_attachment_primary UNION ALL SELECT * FROM file_shadow_sources_attachment_derivative_derived;

CREATE VIEW file_shadow_sources_direct AS SELECT * FROM file_shadow_sources_event_primary UNION ALL SELECT * FROM file_shadow_sources_event_thumbnail UNION ALL SELECT * FROM file_shadow_sources_import_workbook UNION ALL SELECT * FROM file_shadow_sources_import_manifest UNION ALL SELECT * FROM file_shadow_sources_template_version_source;

CREATE VIEW file_shadow_sources AS SELECT * FROM file_shadow_sources_relational UNION ALL SELECT * FROM file_shadow_sources_content UNION ALL SELECT * FROM file_shadow_sources_direct;

CREATE VIEW file_shadow_source_keys_relational AS SELECT 'state_representation_asset' consumer_kind,x.state_hash consumer_id,x.asset_id consumer_sub_id,'primary' file_slot,x.rowid source_rowid FROM state_representation_assets x  UNION ALL SELECT 'run_step_asset' consumer_kind,x.id consumer_id,'' consumer_sub_id,'primary' file_slot,x.rowid source_rowid FROM run_step_assets x  UNION ALL SELECT 'metrology_template_reference' consumer_kind,x.id consumer_id,'' consumer_sub_id,'primary' file_slot,x.rowid source_rowid FROM metrology_template_references x  UNION ALL SELECT 'run_step_comment' consumer_kind,x.id consumer_id,'' consumer_sub_id,'primary' file_slot,x.rowid source_rowid FROM run_step_comments x WHERE (x.asset_id IS NOT NULL) UNION ALL SELECT 'state_verification' consumer_kind,x.id consumer_id,'' consumer_sub_id,'evidence' file_slot,x.rowid source_rowid FROM state_verifications x WHERE (x.evidence_asset_id IS NOT NULL);

CREATE VIEW file_shadow_source_keys_content AS SELECT 'comment_submission_item' consumer_kind,x.id consumer_id,'' consumer_sub_id,'primary' file_slot,x.rowid source_rowid FROM comment_submission_items x WHERE (x.kind<>'link' OR x.asset_id IS NOT NULL OR x.storage_object_id IS NOT NULL) UNION ALL SELECT 'project_content_attachment' consumer_kind,x.project_content_id consumer_id,'' consumer_sub_id,'primary' file_slot,x.rowid source_rowid FROM project_content_attachments x  UNION ALL SELECT 'attachment_derivative' consumer_kind,x.id consumer_id,'' consumer_sub_id,'derived' file_slot,x.rowid source_rowid FROM attachment_derivatives x ;

CREATE VIEW file_shadow_source_keys_direct AS SELECT 'event' consumer_kind,x.id consumer_id,'' consumer_sub_id,'primary' file_slot,x.rowid source_rowid FROM events x WHERE (x.asset_key IS NOT NULL) UNION ALL SELECT 'event' consumer_kind,x.id consumer_id,'' consumer_sub_id,'thumbnail' file_slot,x.rowid source_rowid FROM events x WHERE ( CASE WHEN json_valid(x.metadata_json) THEN json_type(x.metadata_json,'$.thumbnailKey')<>'null' END ) UNION ALL SELECT 'import' consumer_kind,x.id consumer_id,'' consumer_sub_id,'workbook' file_slot,x.rowid source_rowid FROM imports x WHERE (x.workbook_asset_key IS NOT NULL OR x.client_request_id IS NOT NULL) UNION ALL SELECT 'import' consumer_kind,x.id consumer_id,'' consumer_sub_id,'manifest' file_slot,x.rowid source_rowid FROM imports x WHERE (x.manifest_asset_key IS NOT NULL OR x.client_request_id IS NOT NULL) UNION ALL SELECT 'template_version' consumer_kind,x.id consumer_id,'' consumer_sub_id,'source' file_slot,x.rowid source_rowid FROM template_versions x WHERE (x.source_asset_key IS NOT NULL);

CREATE VIEW file_shadow_source_keys AS SELECT * FROM file_shadow_source_keys_relational UNION ALL SELECT * FROM file_shadow_source_keys_content UNION ALL SELECT * FROM file_shadow_source_keys_direct;

CREATE VIEW file_shadow_namespace_mapping AS SELECT m.store_kind,m.provider,m.object_key,l.storage_profile_id,p.configuration_revision FROM legacy_file_mappings m JOIN file_locations l ON l.id=m.location_id JOIN storage_profiles p ON p.id=l.storage_profile_id;

CREATE VIEW file_shadow_namespace_uploads AS SELECT 'r2','r2',r.candidate_object_key,r.storage_profile_id,r.storage_profile_revision FROM r2_upload_requests r UNION SELECT 'r2','r2', CASE WHEN json_valid(r.accepted_result_json) THEN json_extract(r.accepted_result_json,'$.key') END ,r.storage_profile_id,r.storage_profile_revision FROM r2_upload_requests r WHERE r.status='ready' UNION SELECT 'r2','r2',r.candidate_object_key,r.storage_profile_id,r.storage_profile_revision FROM metrology_reference_upload_requests r UNION SELECT 'r2','r2', CASE WHEN json_valid(r.accepted_result_json) THEN json_extract(r.accepted_result_json,'$.reference.assetKey') END ,r.storage_profile_id,r.storage_profile_revision FROM metrology_reference_upload_requests r WHERE r.status='ready';

CREATE VIEW file_shadow_namespace_comments AS SELECT CASE WHEN r.purpose='research_source' THEN 'managed' ELSE 'r2' END , CASE WHEN r.purpose='research_source' THEN 'switchdrive' ELSE 'r2' END ,r.candidate_object_key,r.storage_profile_id,r.storage_profile_revision FROM comment_item_acceptances r UNION SELECT CASE WHEN json_valid(r.accepted_result_json) THEN json_extract(r.accepted_result_json,'$.storeKind') END , CASE WHEN json_valid(r.accepted_result_json) THEN json_extract(r.accepted_result_json,'$.provider') END , CASE WHEN json_valid(r.accepted_result_json) THEN json_extract(r.accepted_result_json,'$.objectKey') END ,r.storage_profile_id,r.storage_profile_revision FROM comment_item_acceptances r WHERE r.status='ready';

CREATE VIEW file_shadow_namespace_imports AS SELECT 'r2','r2',i.workbook_asset_key,i.storage_profile_id,i.storage_profile_revision FROM imports i WHERE i.client_request_id IS NOT NULL UNION SELECT 'r2','r2',i.manifest_asset_key,i.storage_profile_id,i.storage_profile_revision FROM imports i WHERE i.client_request_id IS NOT NULL UNION SELECT 'r2','r2',a.r2_key,i.storage_profile_id,i.storage_profile_revision FROM assets a JOIN imports i ON i.id=a.import_id WHERE i.client_request_id IS NOT NULL;

CREATE VIEW file_shadow_namespace_evidence AS SELECT * FROM file_shadow_namespace_mapping UNION SELECT * FROM file_shadow_namespace_uploads UNION SELECT * FROM file_shadow_namespace_comments UNION SELECT * FROM file_shadow_namespace_imports;

CREATE INDEX file_shadow_dependency_assets_key_idx ON assets(json_array( CASE WHEN typeof(id)='blob' THEN json_object('$sqliteBlob',hex(id)) ELSE id END ));

INSERT INTO file_shadow_dependency_versions(dependency_kind,dependency_key,revision,present,snapshot_json)
  SELECT 'assets',json_array( CASE WHEN typeof(x.id)='blob' THEN json_object('$sqliteBlob',hex(x.id)) ELSE x.id END ),COALESCE((SELECT MAX(v.revision) FROM file_shadow_dependency_versions v WHERE v.dependency_kind='assets' AND v.dependency_key=json_array( CASE WHEN typeof(x.id)='blob' THEN json_object('$sqliteBlob',hex(x.id)) ELSE x.id END )),0)+1,1,json_object('id', CASE WHEN typeof(x.id)='blob' THEN json_object('$sqliteBlob',hex(x.id)) ELSE x.id END ,'import_id', CASE WHEN typeof(x.import_id)='blob' THEN json_object('$sqliteBlob',hex(x.import_id)) ELSE x.import_id END ,'r2_key', CASE WHEN typeof(x.r2_key)='blob' THEN json_object('$sqliteBlob',hex(x.r2_key)) ELSE x.r2_key END ,'status', CASE WHEN typeof(x.status)='blob' THEN json_object('$sqliteBlob',hex(x.status)) ELSE x.status END ,'sha256', CASE WHEN typeof(x.sha256)='blob' THEN json_object('$sqliteBlob',hex(x.sha256)) ELSE x.sha256 END ,'byte_size', CASE WHEN typeof(x.byte_size)='blob' THEN json_object('$sqliteBlob',hex(x.byte_size)) ELSE x.byte_size END ,'created_at', CASE WHEN typeof(x.created_at)='blob' THEN json_object('$sqliteBlob',hex(x.created_at)) ELSE x.created_at END )
  FROM assets x WHERE NOT EXISTS(SELECT 1 FROM file_shadow_dependency_versions v WHERE v.dependency_kind='assets' AND v.dependency_key=json_array( CASE WHEN typeof(x.id)='blob' THEN json_object('$sqliteBlob',hex(x.id)) ELSE x.id END ) AND v.revision=(SELECT MAX(w.revision) FROM file_shadow_dependency_versions w WHERE w.dependency_kind=v.dependency_kind AND w.dependency_key=v.dependency_key) AND v.present=1 AND v.snapshot_json IS json_object('id', CASE WHEN typeof(x.id)='blob' THEN json_object('$sqliteBlob',hex(x.id)) ELSE x.id END ,'import_id', CASE WHEN typeof(x.import_id)='blob' THEN json_object('$sqliteBlob',hex(x.import_id)) ELSE x.import_id END ,'r2_key', CASE WHEN typeof(x.r2_key)='blob' THEN json_object('$sqliteBlob',hex(x.r2_key)) ELSE x.r2_key END ,'status', CASE WHEN typeof(x.status)='blob' THEN json_object('$sqliteBlob',hex(x.status)) ELSE x.status END ,'sha256', CASE WHEN typeof(x.sha256)='blob' THEN json_object('$sqliteBlob',hex(x.sha256)) ELSE x.sha256 END ,'byte_size', CASE WHEN typeof(x.byte_size)='blob' THEN json_object('$sqliteBlob',hex(x.byte_size)) ELSE x.byte_size END ,'created_at', CASE WHEN typeof(x.created_at)='blob' THEN json_object('$sqliteBlob',hex(x.created_at)) ELSE x.created_at END ));
  INSERT INTO file_shadow_dependency_versions(dependency_kind,dependency_key,revision,present,snapshot_json)
  SELECT v.dependency_kind,v.dependency_key,v.revision+1,0,'null' FROM file_shadow_dependency_versions v
  WHERE v.dependency_kind='assets' AND v.present=1 AND v.revision=(SELECT MAX(w.revision) FROM file_shadow_dependency_versions w WHERE w.dependency_kind=v.dependency_kind AND w.dependency_key=v.dependency_key)
  AND NOT EXISTS(SELECT 1 FROM assets x WHERE json_array( CASE WHEN typeof(x.id)='blob' THEN json_object('$sqliteBlob',hex(x.id)) ELSE x.id END )=v.dependency_key);

