CREATE TRIGGER file_shadow_control_insert_guard BEFORE INSERT ON file_shadow_control BEGIN SELECT RAISE(ABORT,'Shadow control already exists') WHERE 1; END;

CREATE TRIGGER file_shadow_control_update_guard BEFORE UPDATE ON file_shadow_control BEGIN SELECT RAISE(ABORT,'Shadow epoch must advance exactly once') WHERE NEW.singleton<>OLD.singleton OR NEW.epoch<>OLD.epoch+1; END;

CREATE TRIGGER file_shadow_control_delete_guard BEFORE DELETE ON file_shadow_control BEGIN SELECT RAISE(ABORT,'Shadow control cannot be deleted') WHERE 1; END;

CREATE TRIGGER file_shadow_runtime_insert_guard BEFORE INSERT ON file_shadow_runtime_guard BEGIN SELECT RAISE(ABORT,'Shadow runtime guard already exists') WHERE 1; END;

CREATE TRIGGER file_shadow_runtime_delete_guard BEFORE DELETE ON file_shadow_runtime_guard BEGIN SELECT RAISE(ABORT,'Shadow runtime guard cannot be deleted') WHERE 1; END;

CREATE TRIGGER file_shadow_runtime_update_guard BEFORE UPDATE ON file_shadow_runtime_guard BEGIN SELECT RAISE(ABORT,'Shadow execution requires a fresh explicitly enabled incarnation') WHERE NEW.singleton<>OLD.singleton OR (NEW.enabled=1 AND (NEW.incarnation IS OLD.incarnation OR EXISTS(SELECT 1 FROM file_shadow_runtime_incarnations h WHERE h.incarnation=NEW.incarnation) OR EXISTS(SELECT 1 FROM file_shadow_attempts a WHERE a.runtime_incarnation=NEW.incarnation) OR NOT EXISTS(SELECT 1 FROM file_authority_control WHERE singleton=1 AND mode='overlap'))) OR (NEW.enabled=0 AND NEW.incarnation IS NOT OLD.incarnation); END;

CREATE TRIGGER file_shadow_runtime_incarnations_admission_guard BEFORE INSERT ON file_shadow_runtime_incarnations BEGIN SELECT RAISE(ABORT,'Runtime incarnation history must match explicit local enablement') WHERE NOT EXISTS(SELECT 1 FROM file_shadow_runtime_guard g WHERE g.singleton=1 AND g.enabled=1 AND g.incarnation=NEW.incarnation AND g.enabled_by=NEW.enabled_by AND g.updated_at=NEW.enabled_at); END;

CREATE TRIGGER file_shadow_runtime_remember AFTER UPDATE ON file_shadow_runtime_guard WHEN NEW.enabled=1 BEGIN INSERT INTO file_shadow_runtime_incarnations(incarnation,enabled_by,enabled_at) VALUES(NEW.incarnation,NEW.enabled_by,NEW.updated_at); END;

CREATE TRIGGER file_shadow_enablements_admission_guard BEFORE INSERT ON file_shadow_enablements BEGIN SELECT RAISE(ABORT,'Shadow enablement baseline changed') WHERE NEW.expected_epoch<>(SELECT epoch FROM file_shadow_control WHERE singleton=1) OR NOT EXISTS(SELECT 1 FROM file_authority_control WHERE singleton=1 AND mode='legacy'); END;

DROP TRIGGER file_authority_control_update_guard;

CREATE TRIGGER file_authority_control_update_guard BEFORE UPDATE ON file_authority_control BEGIN SELECT RAISE(ABORT,'File authority requires explicit shadow enablement; activation remains unavailable') WHERE NOT(OLD.singleton=1 AND NEW.singleton=1 AND OLD.mode='legacy' AND NEW.mode='overlap' AND OLD.revision=1 AND NEW.revision=1 AND EXISTS(SELECT 1 FROM file_shadow_enablements e WHERE e.singleton=1 AND e.expected_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1) AND NEW.updated_at IS e.enabled_at AND NEW.activated_at IS e.enabled_at)); END;

CREATE TRIGGER file_shadow_enablements_apply AFTER INSERT ON file_shadow_enablements BEGIN UPDATE file_authority_control SET mode='overlap',updated_at=NEW.enabled_at,activated_at=NEW.enabled_at WHERE singleton=1; END;

