id AND s.source_json IS NEW.source_json AND s.legacy_store_kind IS NEW.legacy_store_kind AND s.legacy_provider IS NEW.legacy_provider AND s.legacy_object_key IS NEW.legacy_object_key AND s.expected_purpose IS NEW.expected_purpose) WHEN 'state_verification/evidence' THEN EXISTS(SELECT 1 FROM file_shadow_sources_state_verification_evidence s WHERE s.consumer_kind IS NEW.consumer_kind AND s.consumer_id IS NEW.consumer_id AND s.consumer_sub_id IS NEW.consumer_sub_id AND s.file_slot IS NEW.file_slot AND s.source_rowid IS NEW.source_rowid AND s.source_json IS NEW.source_json AND s.legacy_store_kind IS NEW.legacy_store_kind AND s.legacy_provider IS NEW.legacy_provider AND s.legacy_object_key IS NEW.legacy_object_key AND s.expected_purpose IS NEW.expected_purpose) WHEN 'comment_submission_item/primary' THEN EXISTS(SELECT 1 FROM file_shadow_sources_comment_submission_item_primary s WHERE s.consumer_kind IS NEW.consumer_kind AND s.consumer_id IS NEW.consumer_id AND s.consumer_sub_id IS NEW.consumer_sub_id AND s.file_slot IS NEW.file_slot AND s.source_rowid IS NEW.source_rowid AND s.source_json IS NEW.source_json AND s.legacy_store_kind IS NEW.legacy_store_kind AND s.legacy_provider IS NEW.legacy_provider AND s.legacy_object_key IS NEW.legacy_object_key AND s.expected_purpose IS NEW.expected_purpose) WHEN 'project_content_attachment/primary' THEN EXISTS(SELECT 1 FROM file_shadow_sources_project_content_attachment_primary s WHERE s.consumer_kind IS NEW.consumer_kind AND s.consumer_id IS NEW.consumer_id AND s.consumer_sub_id IS NEW.consumer_sub_id AND s.file_slot IS NEW.file_slot AND s.source_rowid IS NEW.source_rowid AND s.source_json IS NEW.source_json AND s.legacy_store_kind IS NEW.legacy_store_kind AND s.legacy_provider IS NEW.legacy_provider AND s.legacy_object_key IS NEW.legacy_object_key AND s.expected_purpose IS NEW.expected_purpose) WHEN 'attachment_derivative/derived' THEN EXISTS(SELECT 1 FROM file_shadow_sources_attachment_derivative_derived s WHERE s.consumer_kind IS NEW.consumer_kind AND s.consumer_id IS NEW.consumer_id AND s.consumer_sub_id IS NEW.consumer_sub_id AND s.file_slot IS NEW.file_slot AND s.source_rowid IS NEW.source_rowid AND s.source_json IS NEW.source_json AND s.legacy_store_kind IS NEW.legacy_store_kind AND s.legacy_provider IS NEW.legacy_provider AND s.legacy_object_key IS NEW.legacy_object_key AND s.expected_purpose IS NEW.expected_purpose) WHEN 'event/primary' THEN EXISTS(SELECT 1 FROM file_shadow_sources_event_primary s WHERE s.consumer_kind IS NEW.consumer_kind AND s.consumer_id IS NEW.consumer_id AND s.consumer_sub_id IS NEW.consumer_sub_id AND s.file_slot IS NEW.file_slot AND s.source_rowid IS NEW.source_rowid AND s.source_json IS NEW.source_json AND s.legacy_store_kind IS NEW.legacy_store_kind AND s.legacy_provider IS NEW.legacy_provider AND s.legacy_object_key IS NEW.legacy_object_key AND s.expected_purpose IS NEW.expected_purpose) WHEN 'event/thumbnail' THEN EXISTS(SELECT 1 FROM file_shadow_sources_event_thumbnail s WHERE s.consumer_kind IS NEW.consumer_kind AND s.consumer_id IS NEW.consumer_id AND s.consumer_sub_id IS NEW.consumer_sub_id AND s.file_slot IS NEW.file_slot AND s.source_rowid IS NEW.source_rowid AND s.source_json IS NEW.source_json AND s.legacy_store_kind IS NEW.legacy_store_kind AND s.legacy_provider IS NEW.legacy_provider AND s.legacy_object_key IS NEW.legacy_object_key AND s.expected_purpose IS NEW.expected_purpose) WHEN 'import/workbook' THEN EXISTS(SELECT 1 FROM file_shadow_sources_import_workbook s WHERE s.consumer_kind IS NEW.consumer_kind AND s.consumer_id IS NEW.consumer_id AND s.consumer_sub_id IS NEW.consumer_sub_id AND s.file_slot IS NEW.file_slot AND s.source_rowid IS NEW.source_rowid AND s.source_json IS NEW.source_json AND s.legacy_store_kind IS NEW.legacy_store_kind AND s.legacy_provider IS NEW.legacy_provider AND s.legacy_object_key IS NEW.legacy_object_key AND s.expected_purpose IS NEW.expected_purpose) WHEN 'import/manifest' THEN EXISTS(SELECT 1 FROM file_shadow_sources_import_manifest s WHERE s.consumer_kind IS NEW.consumer_kind AND s.consumer_id IS NEW.consumer_id AND s.consumer_sub_id IS NEW.consumer_sub_id AND s.file_slot IS NEW.file_slot AND s.source_rowid IS NEW.source_rowid AND s.source_json IS NEW.source_json AND s.legacy_store_kind IS NEW.legacy_store_kind AND s.legacy_provider IS NEW.legacy_provider AND s.legacy_object_key IS NEW.legacy_object_key AND s.expected_purpose IS NEW.expected_purpose) WHEN 'template_version/source' THEN EXISTS(SELECT 1 FROM file_shadow_sources_template_version_source s WHERE s.consumer_kind IS NEW.consumer_kind AND s.consumer_id IS NEW.consumer_id AND s.consumer_sub_id IS NEW.consumer_sub_id AND s.file_slot IS NEW.file_slot AND s.source_rowid IS NEW.source_rowid AND s.source_json IS NEW.source_json AND s.legacy_store_kind IS NEW.legacy_store_kind AND s.legacy_provider IS NEW.legacy_provider AND s.legacy_object_key IS NEW.legacy_object_key AND s.expected_purpose IS NEW.expected_purpose) ELSE 0 END ))
 OR (NEW.present=0 AND (NEW.source_json<>'{}' OR NOT EXISTS(SELECT 1 FROM file_shadow_heads h WHERE h.consumer_kind IS NEW.consumer_kind AND h.consumer_id IS NEW.consumer_id AND h.consumer_sub_id IS NEW.consumer_sub_id AND h.file_slot IS NEW.file_slot AND h.present=1) OR EXISTS(SELECT 1 FROM file_shadow_source_keys s WHERE s.consumer_kind IS NEW.consumer_kind AND s.consumer_id IS NEW.consumer_id AND s.consumer_sub_id IS NEW.consumer_sub_id AND s.file_slot IS NEW.file_slot))); END;

CREATE TRIGGER file_shadow_closures_owner_guard BEFORE INSERT ON file_shadow_closures BEGIN SELECT RAISE(ABORT,'Shadow closure does not match its successor') WHERE NOT EXISTS(SELECT 1 FROM file_shadow_occurrences old JOIN file_shadow_occurrences next ON old.consumer_kind IS next.consumer_kind AND old.consumer_id IS next.consumer_id AND old.consumer_sub_id IS next.consumer_sub_id AND old.file_slot IS next.file_slot AND next.generation=old.generation+1 JOIN file_shadow_heads h ON h.occurrence_id=old.id WHERE old.id=NEW.occurrence_id AND next.id=NEW.successor_occurrence_id AND next.observed_epoch=NEW.closed_epoch AND next.observed_at IS NEW.closed_at); END;

CREATE TRIGGER file_shadow_heads_insert_guard BEFORE INSERT ON file_shadow_heads BEGIN SELECT RAISE(ABORT,'Shadow head does not match its current occurrence') WHERE NOT(EXISTS(SELECT 1 FROM file_shadow_occurrences o WHERE o.id=NEW.occurrence_id AND o.consumer_kind IS NEW.consumer_kind AND o.consumer_id IS NEW.consumer_id AND o.consumer_sub_id IS NEW.consumer_sub_id AND o.file_slot IS NEW.file_slot AND o.generation=NEW.generation AND o.present=NEW.present AND o.source_rowid IS NEW.source_rowid AND o.source_json IS NEW.source_json AND o.observed_epoch=NEW.observed_epoch AND NOT EXISTS(SELECT 1 FROM file_shadow_closures c WHERE c.occurrence_id=o.id))); END;

CREATE TRIGGER file_shadow_heads_update_guard BEFORE UPDATE ON file_shadow_heads BEGIN SELECT RAISE(ABORT,'Shadow head must advance through its recorded closure') WHERE NEW.consumer_kind IS NOT OLD.consumer_kind OR NEW.consumer_id IS NOT OLD.consumer_id OR NEW.consumer_sub_id IS NOT OLD.consumer_sub_id OR NEW.file_slot IS NOT OLD.file_slot OR NEW.generation<>OLD.generation+1 OR NOT(EXISTS(SELECT 1 FROM file_shadow_occurrences o WHERE o.id=NEW.occurrence_id AND o.consumer_kind IS NEW.consumer_kind AND o.consumer_id IS NEW.consumer_id AND o.consumer_sub_id IS NEW.consumer_sub_id AND o.file_slot IS NEW.file_slot AND o.generation=NEW.generation AND o.present=NEW.present AND o.source_rowid IS NEW.source_rowid AND o.source_json IS NEW.source_json AND o.observed_epoch=NEW.observed_epoch AND NOT EXISTS(SELECT 1 FROM file_shadow_closures c WHERE c.occurrence_id=o.id))) OR NOT EXISTS(SELECT 1 FROM file_shadow_closures c WHERE c.occurrence_id=OLD.occurrence_id AND c.successor_occurrence_id=NEW.occurrence_id); END;

CREATE TRIGGER file_shadow_heads_delete_guard BEFORE DELETE ON file_shadow_heads BEGIN SELECT RAISE(ABORT,'Shadow tombstone heads cannot be deleted') WHERE 1; END;

CREATE TRIGGER file_shadow_capture_state_representation_assets_insert AFTER INSERT ON state_representation_assets BEGIN UPDATE file_shadow_control SET epoch=epoch+1 WHERE singleton=1;  INSERT INTO file_shadow_occurrences(id,consumer_kind,consumer_id,consumer_sub_id,file_slot,generation,present,source_rowid,source_json,legacy_store_kind,legacy_provider,legacy_object_key,expected_purpose,observed_epoch,observed_at)
    SELECT 'shadow:'||lower(hex(randomblob(16))),s.consumer_kind,s.consumer_id,s.consumer_sub_id,s.file_slot,COALESCE(h.generation,0)+1,1,s.source_rowid,s.source_json,s.legacy_store_kind,s.legacy_provider,s.legacy_object_key,s.expected_purpose,(SELECT epoch FROM file_shadow_control WHERE singleton=1),strftime('%Y-%m-%dT%H:%M:%fZ','now')
    FROM (WITH current_sources AS MATERIALIZED (SELECT * FROM file_shadow_sources) SELECT * FROM current_sources) s LEFT JOIN file_shadow_heads h ON h.consumer_kind IS s.consumer_kind AND h.consumer_id IS s.consumer_id AND h.consumer_sub_id IS s.consumer_sub_id AND h.file_slot IS s.file_slot WHERE (1=1) AND (h.occurrence_id IS NULL OR h.present<>1 OR h.source_rowid IS NOT s.source_rowid OR h.source_json IS NOT s.source_json OR ((s.consumer_kind='state_representation_asset' AND s.file_slot='primary' AND s.consumer_id IS NEW.state_hash AND s.consumer_sub_id IS NEW.asset_id)));
    INSERT INTO file_shadow_occurrences(id,consumer_kind,consumer_id,consumer_sub_id,file_slot,generation,present,source_rowid,source_json,legacy_store_kind,legacy_provider,legacy_object_key,expected_purpose,observed_epoch,observed_at)
    SELECT 'shadow:'||lower(hex(randomblob(16))),h.consumer_kind,h.consumer_id,h.consumer_sub_id,h.file_slot,h.generation+1,0,NULL,'{}',NULL,NULL,NULL,NULL,(SELECT epoch FROM file_shadow_control WHERE singleton=1),strftime('%Y-%m-%dT%H:%M:%fZ','now')
    FROM file_shadow_heads h WHERE h.present=1 AND (1=1) AND NOT EXISTS(SELECT 1 FROM file_shadow_source_keys s WHERE h.consumer_kind IS s.consumer_kind AND h.consumer_id IS s.consumer_id AND h.consumer_sub_id IS s.consumer_sub_id AND h.file_slot IS s.file_slot);
    INSERT INTO file_shadow_closures(occurrence_id,successor_occurrence_id,closed_epoch,closed_at)
    SELECT h.occurrence_id,o.id,o.observed_epoch,o.observed_at FROM file_shadow_occurrences o JOIN file_shadow_heads h ON h.consumer_kind IS o.consumer_kind AND h.consumer_id IS o.consumer_id AND h.consumer_sub_id IS o.consumer_sub_id AND h.file_slot IS o.file_slot AND o.generation=h.generation+1
    WHERE o.observed_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1);
    INSERT INTO file_shadow_heads(consumer_kind,consumer_id,consumer_sub_id,file_slot,generation,occurrence_id,present,source_rowid,source_json,observed_epoch)
    SELECT o.consumer_kind,o.consumer_id,o.consumer_sub_id,o.file_slot,o.generation,o.id,o.present,o.source_rowid,o.source_json,o.observed_epoch FROM file_shadow_occurrences o
    WHERE o.observed_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1) AND NOT EXISTS(SELECT 1 FROM file_shadow_closures c WHERE c.occurrence_id=o.id)
    ON CONFLICT(consumer_kind,consumer_id,consumer_sub_id,file_slot) DO UPDATE SET generation=excluded.generation,occurrence_id=excluded.occurrence_id,present=excluded.present,source_rowid=excluded.source_rowid,source_json=excluded.source_json,observed_epoch=excluded.observed_epoch
    WHERE file_shadow_heads.generation<excluded.generation; END;

