    SELECT h.occurrence_id,o.id,o.observed_epoch,o.observed_at FROM file_shadow_occurrences o JOIN file_shadow_heads h ON h.consumer_kind IS o.consumer_kind AND h.consumer_id IS o.consumer_id AND h.consumer_sub_id IS o.consumer_sub_id AND h.file_slot IS o.file_slot AND o.generation=h.generation+1
    WHERE o.observed_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1);
    INSERT INTO file_shadow_heads(consumer_kind,consumer_id,consumer_sub_id,file_slot,generation,occurrence_id,present,source_rowid,source_json,observed_epoch)
    SELECT o.consumer_kind,o.consumer_id,o.consumer_sub_id,o.file_slot,o.generation,o.id,o.present,o.source_rowid,o.source_json,o.observed_epoch FROM file_shadow_occurrences o
    WHERE o.observed_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1) AND NOT EXISTS(SELECT 1 FROM file_shadow_closures c WHERE c.occurrence_id=o.id)
    ON CONFLICT(consumer_kind,consumer_id,consumer_sub_id,file_slot) DO UPDATE SET generation=excluded.generation,occurrence_id=excluded.occurrence_id,present=excluded.present,source_rowid=excluded.source_rowid,source_json=excluded.source_json,observed_epoch=excluded.observed_epoch
    WHERE file_shadow_heads.generation<excluded.generation; END;

DROP TRIGGER storage_profile_runtime_legacy_update_guard;

CREATE TRIGGER storage_profile_runtime_legacy_update_guard BEFORE UPDATE ON storage_profile_runtime BEGIN SELECT RAISE(ABORT,'Profile write readiness requires explicit shadow admission') WHERE NOT(EXISTS(SELECT 1 FROM file_authority_control WHERE singleton=1 AND mode='overlap')) OR OLD.state<>'read_only' OR NEW.state<>'read_write' OR NEW.storage_profile_id IS NOT OLD.storage_profile_id OR NEW.registered_at IS NOT OLD.registered_at OR NEW.retired_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM file_shadow_profile_enablements e WHERE e.storage_profile_id=NEW.storage_profile_id AND NEW.activated_at IS e.enabled_at); END;

CREATE TRIGGER file_shadow_profile_enablements_admission_guard BEFORE INSERT ON file_shadow_profile_enablements BEGIN SELECT RAISE(ABORT,'Profile enablement does not match a read-only historical instance') WHERE NOT(EXISTS(SELECT 1 FROM file_authority_control WHERE singleton=1 AND mode='overlap')) OR NOT EXISTS(SELECT 1 FROM storage_profiles p JOIN storage_profile_runtime r ON r.storage_profile_id=p.id WHERE p.id=NEW.storage_profile_id AND p.configuration_revision=NEW.configuration_revision AND r.state='read_only'); END;

CREATE TRIGGER file_shadow_profile_enablements_apply AFTER INSERT ON file_shadow_profile_enablements BEGIN UPDATE storage_profile_runtime SET state='read_write',activated_at=NEW.enabled_at WHERE storage_profile_id=NEW.storage_profile_id; END;

CREATE TRIGGER file_shadow_operations_replace_guard BEFORE INSERT ON file_shadow_operations BEGIN SELECT RAISE(ABORT,'Shadow operation identity already exists') WHERE EXISTS(SELECT 1 FROM file_shadow_operations WHERE id=NEW.id); END;

CREATE TRIGGER file_shadow_operations_delete_guard BEFORE DELETE ON file_shadow_operations BEGIN SELECT RAISE(ABORT,'Shadow operation history cannot be deleted') WHERE 1; END;

CREATE TRIGGER file_shadow_attempts_replace_guard BEFORE INSERT ON file_shadow_attempts BEGIN SELECT RAISE(ABORT,'Shadow operation identity already exists') WHERE EXISTS(SELECT 1 FROM file_shadow_attempts WHERE id=NEW.id); END;

CREATE TRIGGER file_shadow_attempts_delete_guard BEFORE DELETE ON file_shadow_attempts BEGIN SELECT RAISE(ABORT,'Shadow operation history cannot be deleted') WHERE 1; END;

CREATE TRIGGER file_shadow_legacy_holds_replace_guard BEFORE INSERT ON file_shadow_legacy_holds BEGIN SELECT RAISE(ABORT,'Shadow operation identity already exists') WHERE EXISTS(SELECT 1 FROM file_shadow_legacy_holds WHERE id=NEW.id); END;

CREATE TRIGGER file_shadow_legacy_holds_delete_guard BEFORE DELETE ON file_shadow_legacy_holds BEGIN SELECT RAISE(ABORT,'Shadow operation history cannot be deleted') WHERE 1; END;

CREATE TRIGGER file_shadow_operations_insert_guard BEFORE INSERT ON file_shadow_operations BEGIN SELECT RAISE(ABORT,'Shadow operation requires a current frozen source generation and exact namespace') WHERE NOT(EXISTS(SELECT 1 FROM file_authority_control WHERE singleton=1 AND mode='overlap')) OR NEW.status<>'pending' OR EXISTS(SELECT 1 FROM file_shadow_decisions d WHERE d.occurrence_id=NEW.occurrence_id) OR NEW.captured_epoch<>(SELECT epoch FROM file_shadow_control WHERE singleton=1) OR NOT EXISTS(SELECT 1 FROM file_shadow_heads h JOIN file_shadow_occurrences o ON o.id=h.occurrence_id WHERE o.id=NEW.occurrence_id AND h.present=1 AND o.legacy_store_kind IS NEW.source_store_kind AND o.legacy_provider IS NEW.source_provider AND o.legacy_object_key IS NEW.source_object_key) OR (NEW.source_profile_id IS NOT NULL AND NOT(EXISTS(SELECT 1 FROM file_shadow_namespace_evidence e WHERE e.store_kind IS NEW.source_store_kind AND e.provider IS NEW.source_provider AND e.object_key IS NEW.source_object_key AND e.storage_profile_id IS NEW.source_profile_id AND e.configuration_revision IS NEW.source_profile_revision)
 AND NOT EXISTS(SELECT 1 FROM file_shadow_namespace_evidence e WHERE e.store_kind IS NEW.source_store_kind AND e.provider IS NEW.source_provider AND e.object_key IS NEW.source_object_key AND (e.storage_profile_id IS NOT NEW.source_profile_id OR e.configuration_revision IS NOT NEW.source_profile_revision)))); END;

CREATE TRIGGER file_shadow_operations_update_guard BEFORE UPDATE ON file_shadow_operations BEGIN SELECT RAISE(ABORT,'Shadow operation contract and terminal state are immutable') WHERE NEW.id IS NOT OLD.id OR NEW.occurrence_id IS NOT OLD.occurrence_id OR NEW.captured_epoch IS NOT OLD.captured_epoch OR NEW.baseline_sha256 IS NOT OLD.baseline_sha256 OR NEW.purpose IS NOT OLD.purpose OR NEW.access_scope IS NOT OLD.access_scope OR NEW.source_store_kind IS NOT OLD.source_store_kind OR NEW.source_provider IS NOT OLD.source_provider OR NEW.source_object_key IS NOT OLD.source_object_key OR NEW.source_profile_id IS NOT OLD.source_profile_id OR NEW.source_profile_revision IS NOT OLD.source_profile_revision OR NEW.source_expected_byte_size IS NOT OLD.source_expected_byte_size OR NEW.source_expected_sha256 IS NOT OLD.source_expected_sha256 OR NEW.destination_profile_id IS NOT OLD.destination_profile_id OR NEW.destination_profile_revision IS NOT OLD.destination_profile_revision OR NEW.created_by IS NOT OLD.created_by OR NEW.created_at IS NOT OLD.created_at OR OLD.status<>'pending' OR NEW.status='pending' OR (NEW.status IN('resolved','admitted_unresolved') AND NOT EXISTS(SELECT 1 FROM file_shadow_decisions d WHERE d.operation_id=OLD.id AND d.decision=NEW.status)) OR (NEW.status='cancelled' AND EXISTS(SELECT 1 FROM file_shadow_attempts a WHERE a.operation_id=OLD.id AND(a.write_started_at IS NOT NULL OR a.verified_at IS NOT NULL OR a.state NOT IN('failed','cancelled')))) OR (NEW.status='resolved' AND NOT EXISTS(SELECT 1 FROM file_shadow_attempts a JOIN file_shadow_decisions d ON d.operation_id=a.operation_id AND d.file_id=a.candidate_file_id AND d.location_id=a.candidate_location_id WHERE a.operation_id=OLD.id AND a.state='published')); END;

CREATE TRIGGER file_shadow_attempts_insert_guard BEFORE INSERT ON file_shadow_attempts BEGIN SELECT RAISE(ABORT,'Shadow attempt requires current exclusive operation ownership') WHERE NOT(EXISTS(SELECT 1 FROM file_authority_control WHERE singleton=1 AND mode='overlap')) OR NOT(EXISTS(SELECT 1 FROM file_shadow_runtime_guard g WHERE g.singleton=1 AND g.enabled=1 AND g.incarnation=NEW.runtime_incarnation)) OR NEW.state<>'staged' OR NEW.candidate_file_id IS NOT NULL OR NEW.write_started_at IS NOT NULL OR NEW.verified_at IS NOT NULL OR NEW.completed_at IS NOT NULL OR NEW.attempt_number<>COALESCE((SELECT MAX(attempt_number)+1 FROM file_shadow_attempts a WHERE a.operation_id=NEW.operation_id),1) OR EXISTS(SELECT 1 FROM file_shadow_attempts a WHERE a.operation_id=NEW.operation_id AND a.state IN('staged','write_started','unknown','verified')) OR NOT EXISTS(SELECT 1 FROM file_shadow_operations o JOIN file_shadow_heads h ON h.occurrence_id=o.occurrence_id WHERE o.id=NEW.operation_id AND o.status='pending' AND o.captured_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1) AND h.present=1); END;

CREATE TRIGGER file_shadow_attempts_candidate_insert_guard BEFORE INSERT ON file_shadow_attempts BEGIN SELECT RAISE(ABORT,'Shadow attempt candidate contract mismatch') WHERE NOT(NEW.candidate_file_id IS NULL OR EXISTS(SELECT 1 FROM file_shadow_operations o JOIN files f ON f.id=NEW.candidate_file_id JOIN file_locations l ON l.id=NEW.candidate_location_id AND l.file_id=f.id WHERE o.id=NEW.operation_id AND f.purpose IS o.purpose AND f.access_scope IS o.access_scope AND f.expected_byte_size IS NEW.verified_byte_size AND f.expected_sha256 IS NEW.verified_sha256 AND NEW.verified_byte_size IS o.source_expected_byte_size AND NEW.verified_sha256 IS o.source_expected_sha256 AND l.storage_profile_id IS o.destination_profile_id AND l.object_key IS NEW.candidate_object_key AND NOT(l.storage_profile_id IS o.source_profile_id AND l.object_key IS o.source_object_key) AND (NEW.state IN('verified','published') OR NOT EXISTS(SELECT 1 FROM file_publications p WHERE p.file_id=f.id)) AND NOT EXISTS(SELECT 1 FROM file_location_gc_ledger g WHERE g.location_id=l.id AND g.state IN('deleting','deleted')))); END;

CREATE TRIGGER file_shadow_attempts_update_guard BEFORE UPDATE ON file_shadow_attempts BEGIN SELECT RAISE(ABORT,'Shadow attempt transition or executor fence rejected') WHERE NEW.id IS NOT OLD.id OR NEW.operation_id IS NOT OLD.operation_id OR NEW.attempt_number IS NOT OLD.attempt_number OR NEW.owner_token IS NOT OLD.owner_token OR NEW.runtime_incarnation IS NOT OLD.runtime_incarnation OR NEW.created_at IS NOT OLD.created_at OR NEW.lease_expires_at IS NOT OLD.lease_expires_at OR (OLD.write_started_at IS NOT NULL AND NEW.write_started_at IS NOT OLD.write_started_at) OR (OLD.verified_at IS NOT NULL AND NEW.verified_at IS NOT OLD.verified_at) OR (OLD.completed_at IS NOT NULL AND NEW.completed_at IS NOT OLD.completed_at) OR (OLD.candidate_file_id IS NOT NULL AND (NEW.candidate_file_id IS NOT OLD.candidate_file_id OR NEW.candidate_location_id IS NOT OLD.candidate_location_id OR NEW.candidate_object_key IS NOT OLD.candidate_object_key OR NEW.verified_byte_size IS NOT OLD.verified_byte_size OR NEW.verified_sha256 IS NOT OLD.verified_sha256 OR NEW.source_verified_at IS NOT OLD.source_verified_at)) OR NOT(NEW.candidate_file_id IS NULL OR EXISTS(SELECT 1 FROM file_shadow_operations o JOIN files f ON f.id=NEW.candidate_file_id JOIN file_locations l ON l.id=NEW.candidate_location_id AND l.file_id=f.id WHERE o.id=NEW.operation_id AND f.purpose IS o.purpose AND f.access_scope IS o.access_scope AND f.expected_byte_size IS NEW.verified_byte_size AND f.expected_sha256 IS NEW.verified_sha256 AND NEW.verified_byte_size IS o.source_expected_byte_size AND NEW.verified_sha256 IS o.source_expected_sha256 AND l.storage_profile_id IS o.destination_profile_id AND l.object_key IS NEW.candidate_object_key AND NOT(l.storage_profile_id IS o.source_profile_id AND l.object_key IS o.source_object_key) AND (NEW.state IN('verified','published') OR NOT EXISTS(SELECT 1 FROM file_publications p WHERE p.file_id=f.id)) AND NOT EXISTS(SELECT 1 FROM file_location_gc_ledger g WHERE g.location_id=l.id AND g.state IN('deleting','deleted'))))
 OR NOT((OLD.state='staged' AND NEW.state IN('staged','write_started','failed','cancelled')) OR (OLD.state='write_started' AND NEW.state IN('unknown','verified')) OR (OLD.state='unknown' AND NEW.state IN('unknown','verified')) OR (OLD.state='verified' AND NEW.state IN('published','cancelled')))
 OR (NEW.state IN('write_started','published') AND ((NOT(EXISTS(SELECT 1 FROM file_shadow_runtime_guard g WHERE g.singleton=1 AND g.enabled=1 AND g.incarnation=NEW.runtime_incarnation)) OR julianday(NEW.lease_expires_at)<=julianday('now')) AND NOT(NEW.state='published' AND EXISTS(SELECT 1 FROM file_shadow_reconciliations r JOIN file_shadow_runtime_guard g ON g.enabled=1 AND g.incarnation=r.runtime_incarnation WHERE r.attempt_id=NEW.id AND r.verified_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1) AND r.verified_sha256=NEW.verified_sha256 AND r.verified_byte_size=NEW.verified_byte_size))))
 OR (NEW.state IN('write_started','published') AND NOT EXISTS(SELECT 1 FROM file_shadow_operations o JOIN file_shadow_heads h ON h.occurrence_id=o.occurrence_id JOIN storage_profile_runtime r ON r.storage_profile_id=o.destination_profile_id WHERE o.id=NEW.operation_id AND o.status='pending' AND (o.captured_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1) OR(NEW.state='published' AND EXISTS(SELECT 1 FROM file_shadow_reconciliations r JOIN file_shadow_runtime_guard g ON g.enabled=1 AND g.incarnation=r.runtime_incarnation WHERE r.attempt_id=NEW.id AND r.verified_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1) AND r.verified_sha256=NEW.verified_sha256 AND r.verified_byte_size=NEW.verified_byte_size))) AND h.present=1 AND r.state='read_write'))
 OR (NEW.state='write_started' AND NOT EXISTS(SELECT 1 FROM file_shadow_legacy_holds h WHERE h.operation_id=NEW.operation_id AND h.released_at IS NULL))
 OR (NEW.state='write_started' AND NOT EXISTS(SELECT 1 FROM file_location_holds h WHERE h.operation_id=NEW.operation_id AND h.location_id=NEW.candidate_location_id AND h.hold_kind='transition_destination' AND h.released_at IS NULL AND(h.expires_at IS NULL OR julianday(h.expires_at)>julianday('now'))))
 OR (NEW.state='published' AND NOT EXISTS(SELECT 1 FROM file_shadow_decisions d WHERE d.operation_id=NEW.operation_id AND d.file_id=NEW.candidate_file_id AND d.location_id=NEW.candidate_location_id)); END;

CREATE TRIGGER file_shadow_location_publication_guard BEFORE INSERT ON file_location_publications BEGIN SELECT RAISE(ABORT,'Shadow location publication requires the exact current verified conversion proof') WHERE NOT EXISTS(SELECT 1 FROM file_shadow_attempts a JOIN file_shadow_operations o ON o.id=a.operation_id JOIN file_shadow_heads h ON h.occurrence_id=o.occurrence_id AND h.present=1 WHERE o.id=NEW.verification_operation_id AND o.status='pending' AND a.state='verified' AND a.candidate_file_id=NEW.file_id AND a.candidate_location_id=NEW.location_id AND a.candidate_object_key=NEW.object_key AND o.destination_profile_id=NEW.storage_profile_id AND a.verified_byte_size=NEW.verified_byte_size AND a.verified_sha256=NEW.verified_sha256 AND (o.captured_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1) OR EXISTS(SELECT 1 FROM file_shadow_reconciliations r JOIN file_shadow_runtime_guard g ON g.enabled=1 AND g.incarnation=r.runtime_incarnation WHERE r.attempt_id=a.id AND r.verified_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1) AND r.verified_sha256=a.verified_sha256 AND r.verified_byte_size=a.verified_byte_size)) AND ((EXISTS(SELECT 1 FROM file_shadow_runtime_guard g WHERE g.singleton=1 AND g.enabled=1 AND g.incarnation=a.runtime_incarnation) AND julianday(a.lease_expires_at)>julianday('now')) OR EXISTS(SELECT 1 FROM file_shadow_reconciliations r JOIN file_shadow_runtime_guard g ON g.enabled=1 AND g.incarnation=r.runtime_incarnation WHERE r.attempt_id=a.id AND r.verified_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1) AND r.verified_sha256=a.verified_sha256 AND r.verified_byte_size=a.verified_byte_size))); END;

CREATE TRIGGER file_shadow_file_publication_guard BEFORE INSERT ON file_publications BEGIN SELECT RAISE(ABORT,'Shadow File publication must follow its verified conversion location') WHERE NOT EXISTS(SELECT 1 FROM file_location_publications p JOIN file_shadow_operations o ON o.id=p.verification_operation_id JOIN file_shadow_attempts a ON a.operation_id=o.id AND a.candidate_location_id=p.location_id WHERE p.location_id=NEW.active_location_id AND p.file_id=NEW.file_id AND a.candidate_file_id=NEW.file_id AND a.state='verified' AND o.status='pending' AND NEW.purpose IS o.purpose AND NEW.access_scope IS o.access_scope AND NEW.verified_byte_size=p.verified_byte_size AND NEW.verified_sha256=p.verified_sha256); END;

CREATE TRIGGER file_shadow_decisions_admission_guard BEFORE INSERT ON file_shadow_decisions BEGIN SELECT RAISE(ABORT,'Shadow decision requires a current verified occurrence contract') WHERE NOT(EXISTS(SELECT 1 FROM file_authority_control WHERE singleton=1 AND mode='overlap')) OR NOT EXISTS(SELECT 1 FROM file_shadow_operations o JOIN file_shadow_heads h ON h.occurrence_id=o.occurrence_id WHERE o.id=NEW.operation_id AND o.occurrence_id=NEW.occurrence_id AND o.baseline_sha256 IS NEW.baseline_sha256 AND o.status='pending' AND (o.captured_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1) OR (NEW.decision='resolved' AND EXISTS(SELECT 1 FROM file_shadow_attempts a WHERE a.operation_id=o.id AND EXISTS(SELECT 1 FROM file_shadow_reconciliations r JOIN file_shadow_runtime_guard g ON g.enabled=1 AND g.incarnation=r.runtime_incarnation WHERE r.attempt_id=a.id AND r.verified_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1) AND r.verified_sha256=a.verified_sha256 AND r.verified_byte_size=a.verified_byte_size)))) AND h.present=1)
 OR (NEW.decision='resolved' AND NOT EXISTS(SELECT 1 FROM file_shadow_attempts a JOIN file_shadow_operations o ON o.id=a.operation_id JOIN file_usable_publications f ON f.file_id=NEW.file_id JOIN file_locations l ON l.id=NEW.location_id WHERE a.operation_id=NEW.operation_id AND a.state='verified' AND a.candidate_file_id=f.file_id AND a.candidate_location_id=l.id AND f.active_location_id=l.id AND f.purpose IS o.purpose AND f.access_scope IS o.access_scope AND l.storage_profile_id IS o.destination_profile_id AND f.verified_sha256 IS a.verified_sha256 AND f.verified_byte_size IS a.verified_byte_size AND ((EXISTS(SELECT 1 FROM file_shadow_runtime_guard g WHERE g.singleton=1 AND g.enabled=1 AND g.incarnation=a.runtime_incarnation) AND julianday(a.lease_expires_at)>julianday('now')) OR EXISTS(SELECT 1 FROM file_shadow_reconciliations r JOIN file_shadow_runtime_guard g ON g.enabled=1 AND g.incarnation=r.runtime_incarnation WHERE r.attempt_id=a.id AND r.verified_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1) AND r.verified_sha256=a.verified_sha256 AND r.verified_byte_size=a.verified_byte_size)))); END;

CREATE TRIGGER file_shadow_decisions_purpose_guard BEFORE INSERT ON file_shadow_decisions BEGIN SELECT RAISE(ABORT,'Shadow decision purpose does not match its typed business slot') WHERE NEW.decision='resolved' AND NOT EXISTS(SELECT 1 FROM file_shadow_occurrences o JOIN file_usable_publications f ON f.file_id=NEW.file_id WHERE o.id=NEW.occurrence_id AND f.purpose= CASE WHEN o.consumer_kind IN('state_representation_asset','run_step_asset','run_step_comment','state_verification') OR(o.consumer_kind='event' AND o.file_slot='primary') THEN 'embedded_content' WHEN o.consumer_kind IN('metrology_template_reference','project_content_attachment') THEN 'research_source' WHEN o.consumer_kind IN('import','template_version') THEN 'provenance' WHEN o.consumer_kind='attachment_derivative' OR(o.consumer_kind='event' AND o.file_slot='thumbnail') THEN 'derived_preview' WHEN o.consumer_kind='comment_submission_item' THEN o.expected_purpose END ); END;

CREATE TRIGGER file_shadow_decisions_derivation_guard BEFORE INSERT ON file_shadow_decisions BEGIN SELECT RAISE(ABORT,'Shadow preview binding requires its exact verified derivation') WHERE NEW.decision='resolved' AND EXISTS(SELECT 1 FROM file_shadow_occurrences o JOIN file_usable_publications f ON f.file_id=NEW.file_id WHERE o.id=NEW.occurrence_id AND f.purpose='derived_preview' AND NOT EXISTS(
 SELECT 1 FROM file_derivations d JOIN file_usable_publications source ON source.file_id=d.source_file_id WHERE d.derived_file_id=NEW.file_id AND d.trust_state='verified' AND (
 (o.consumer_kind='attachment_derivative' AND d.generator=json_extract(o.source_json,'$.derivative_kind') AND d.generator_version=json_extract(o.source_json,'$.generator_version') AND d.source_verified_sha256=json_extract(o.source_json,'$.source_sha256') AND source.verified_byte_size=json_extract(o.source_json,'$.source_byte_size'))
 OR (o.consumer_kind='event' AND o.file_slot='thumbnail' AND EXISTS(SELECT 1 FROM file_shadow_heads h JOIN file_shadow_decisions sd ON sd.occurrence_id=h.occurrence_id WHERE h.consumer_kind='event' AND h.consumer_id=o.consumer_id AND h.consumer_sub_id='' AND h.file_slot='primary' AND h.present=1 AND sd.file_id=d.source_file_id))
 OR (o.consumer_kind='comment_submission_item' AND EXISTS(SELECT 1 FROM file_shadow_heads h JOIN file_shadow_decisions sd ON sd.occurrence_id=h.occurrence_id WHERE h.consumer_kind='comment_submission_item' AND h.consumer_id=json_extract(o.source_json,'$.related_item_id') AND h.consumer_sub_id='' AND h.file_slot='primary' AND h.present=1 AND sd.file_id=d.source_file_id))))); END;

CREATE TRIGGER file_shadow_reconciliations_admission_guard BEFORE INSERT ON file_shadow_reconciliations BEGIN SELECT RAISE(ABORT,'Reconciliation must verify the exact frozen attempt in the enabled runtime') WHERE NOT(EXISTS(SELECT 1 FROM file_authority_control WHERE singleton=1 AND mode='overlap')) OR NOT(EXISTS(SELECT 1 FROM file_shadow_runtime_guard g WHERE g.singleton=1 AND g.enabled=1 AND g.incarnation=NEW.runtime_incarnation)) OR NEW.verified_epoch<>(SELECT epoch FROM file_shadow_control WHERE singleton=1) OR NOT EXISTS(SELECT 1 FROM file_shadow_attempts a JOIN file_shadow_operations o ON o.id=a.operation_id JOIN file_shadow_heads h ON h.occurrence_id=o.occurrence_id AND h.present=1 WHERE a.id=NEW.attempt_id AND a.state IN('write_started','unknown','verified') AND a.verified_byte_size=NEW.verified_byte_size AND a.verified_sha256=NEW.verified_sha256 AND o.status='pending' AND julianday(NEW.source_verified_at)>=julianday(a.created_at) AND julianday(NEW.destination_verified_at)>=julianday(a.created_at)); END;

CREATE TRIGGER file_shadow_checkpoints_admission_guard BEFORE INSERT ON file_shadow_checkpoints BEGIN SELECT RAISE(ABORT,'Catch-up checkpoint requires a current complete source graph') WHERE NOT(EXISTS(SELECT 1 FROM file_authority_control WHERE singleton=1 AND mode='overlap')) OR NEW.captured_epoch<>(SELECT epoch FROM file_shadow_control WHERE singleton=1) OR NEW.current_count<>(SELECT count(*) FROM file_shadow_heads WHERE present=1) OR NEW.resolved_count<>(SELECT count(*) FROM file_shadow_heads h JOIN file_shadow_decisions d ON d.occurrence_id=h.occurrence_id JOIN file_usable_publications p ON p.file_id=d.file_id AND p.active_location_id=d.location_id WHERE h.present=1 AND d.decision='resolved') OR NEW.unresolved_count<>(SELECT count(*) FROM file_shadow_heads h JOIN file_shadow_decisions d ON d.occurrence_id=h.occurrence_id WHERE h.present=1 AND d.decision='admitted_unresolved') OR NEW.pending_count<>(SELECT count(*) FROM file_shadow_heads WHERE present=1)-(SELECT count(*) FROM file_shadow_heads h JOIN file_shadow_decisions d ON d.occurrence_id=h.occurrence_id JOIN file_usable_publications p ON p.file_id=d.file_id AND p.active_location_id=d.location_id WHERE h.present=1 AND d.decision='resolved')-(SELECT count(*) FROM file_shadow_heads h JOIN file_shadow_decisions d ON d.occurrence_id=h.occurrence_id WHERE h.present=1 AND d.decision='admitted_unresolved') OR EXISTS(SELECT 1 FROM file_shadow_heads h WHERE h.present=1 AND NOT EXISTS(SELECT 1 FROM file_shadow_sources s WHERE s.consumer_kind IS h.consumer_kind AND s.consumer_id IS h.consumer_id AND s.consumer_sub_id IS h.consumer_sub_id AND s.file_slot IS h.file_slot AND s.source_json IS h.source_json AND s.source_rowid IS h.source_rowid)) OR EXISTS(SELECT 1 FROM file_shadow_sources s WHERE NOT EXISTS(SELECT 1 FROM file_shadow_heads h WHERE h.consumer_kind IS s.consumer_kind AND h.consumer_id IS s.consumer_id AND h.consumer_sub_id IS s.consumer_sub_id AND h.file_slot IS s.file_slot AND h.present=1)); END;

CREATE TRIGGER file_shadow_holds_insert_guard BEFORE INSERT ON file_shadow_legacy_holds BEGIN SELECT RAISE(ABORT,'Shadow source hold cannot cross deletion or a different profile') WHERE NOT(EXISTS(SELECT 1 FROM file_authority_control WHERE singleton=1 AND mode='overlap')) OR NEW.released_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM file_shadow_operations o JOIN storage_profiles p ON p.id=NEW.storage_profile_id WHERE o.id=NEW.operation_id AND o.status='pending' AND o.captured_epoch=(SELECT epoch FROM file_shadow_control WHERE singleton=1) AND o.source_store_kind IS NEW.store_kind AND o.source_provider IS NEW.provider AND o.source_object_key IS NEW.object_key AND o.source_profile_id=NEW.storage_profile_id AND o.source_profile_revision=NEW.profile_revision AND p.adapter_type=NEW.provider AND p.configuration_revision=NEW.profile_revision)
 OR EXISTS(SELECT 1 FROM file_shadow_legacy_deletion_claims g WHERE g.store_kind=NEW.store_kind AND g.provider=NEW.provider AND g.object_key=NEW.object_key)
 OR EXISTS(SELECT 1 FROM file_locations l JOIN file_location_gc_ledger g ON g.location_id=l.id WHERE l.storage_profile_id=NEW.storage_profile_id AND l.object_key=NEW.object_key AND g.state IN('deleting','deleted')); END;

CREATE TRIGGER file_shadow_holds_update_guard BEFORE UPDATE ON file_shadow_legacy_holds BEGIN SELECT RAISE(ABORT,'Shadow hold requires safe terminal reconciliation before release') WHERE NEW.id IS NOT OLD.id OR NEW.operation_id IS NOT OLD.operation_id OR NEW.store_kind IS NOT OLD.store_kind OR NEW.provider IS NOT OLD.provider OR NEW.object_key IS NOT OLD.object_key OR NEW.storage_profile_id IS NOT OLD.storage_profile_id OR NEW.profile_revision IS NOT OLD.profile_revision OR NEW.acquired_at IS NOT OLD.acquired_at OR OLD.released_at IS NOT NULL OR NEW.released_at IS NULL OR NOT EXISTS(SELECT 1 FROM file_shadow_operations o WHERE o.id=NEW.operation_id AND o.status<>'pending') OR EXISTS(SELECT 1 FROM file_shadow_attempts a WHERE a.operation_id=NEW.operation_id AND a.state IN('staged','write_started','unknown','verified')); END;

CREATE VIEW file_retention_edges_legacy_v14 AS
SELECT * FROM file_relational_retention_edges
UNION ALL
SELECT * FROM file_content_retention_edges
UNION ALL
SELECT * FROM file_direct_retention_edges;

CREATE VIEW file_location_retention_edges_legacy_v14 AS
SELECT fp.active_location_id AS location_id, fre.file_id, fre.source_type, fre.source_id,
  fre.occurrence_type, fre.occurrence_id, fre.retention_reason, fre.retain_until
FROM file_retention_edges fre
JOIN file_publications fp ON fp.file_id = fre.file_id AND fp.state = 'ready'

UNION ALL
SELECT fl.id, fl.file_id, 'file' AS source_type, fl.file_id AS source_id,
  'file_hold' AS occurrence_type, h.id AS occurrence_id, h.hold_kind AS retention_reason, h.expires_at
FROM file_holds h
JOIN file_publications fp ON fp.file_id = h.file_id AND fp.state = 'ready'
JOIN file_locations fl ON fl.id = fp.active_location_id
WHERE h.released_at IS NULL AND (h.expires_at IS NULL OR julianday(h.expires_at) > julianday('now'))

UNION ALL
SELECT c.candidate_location_id, c.candidate_file_id, 'file_acceptance_candidate',
  c.acceptance_kind || ':' || c.acceptance_id || ':' || c.item_id,
  'candidate_registration', c.acceptance_kind || ':' || c.acceptance_id || ':' || c.item_id,
  'acceptance_in_flight', NULL
FROM file_acceptance_candidates c
WHERE c.state = 'candidate'

UNION ALL
SELECT h.location_id, fl.file_id, 'file_location', h.location_id,
  'file_location_hold', h.id, h.hold_kind, h.expires_at
FROM file_location_holds h JOIN file_locations fl ON fl.id = h.location_id
WHERE h.released_at IS NULL AND (h.expires_at IS NULL OR julianday(h.expires_at) > julianday('now'));

DROP VIEW file_location_retention_edges; DROP VIEW file_retention_edges;

CREATE VIEW file_shadow_retention_edges AS SELECT d.file_id,'file_shadow_occurrence' AS source_type,h.occurrence_id AS source_id,'file_shadow_publication' AS occurrence_type,h.occurrence_id,'shadow_publication' AS retention_reason,NULL AS retain_until FROM file_shadow_heads h JOIN file_shadow_decisions d ON d.occurrence_id=h.occurrence_id WHERE h.present=1 AND d.decision='resolved';
CREATE VIEW file_retention_edges AS SELECT * FROM file_retention_edges_legacy_v14 UNION ALL SELECT * FROM file_shadow_retention_edges;
CREATE VIEW file_location_retention_edges AS SELECT * FROM file_location_retention_edges_legacy_v14 UNION ALL SELECT d.location_id,d.file_id,'file_shadow_occurrence',h.occurrence_id,'file_shadow_publication',h.occurrence_id,'shadow_publication',NULL FROM file_shadow_heads h JOIN file_shadow_decisions d ON d.occurrence_id=h.occurrence_id WHERE h.present=1 AND d.decision='resolved';

CREATE VIEW blob_retention_edges_legacy_v14 AS
SELECT * FROM blob_retention_edges_r2_occurrences
UNION ALL
SELECT * FROM blob_retention_edges_comment_items
UNION ALL
SELECT * FROM blob_retention_edges_direct_keys
UNION ALL
SELECT * FROM blob_retention_edges_project_attachments
UNION ALL
SELECT * FROM blob_retention_edges_attachment_derivatives;

DROP VIEW blob_retention_edges;

CREATE VIEW file_shadow_legacy_retention_edges AS SELECT h.store_kind,h.provider,h.object_key,NULL AS blob_record_id,'file_shadow_operation' AS source_type,h.operation_id AS source_id,'file_shadow_hold' AS occurrence_type,h.id AS occurrence_id,'shadow_source_hold' AS retention_reason,NULL AS retain_until FROM file_shadow_legacy_holds h WHERE h.released_at IS NULL
UNION ALL SELECT e.store_kind,e.provider,e.object_key,NULL,'file_location',h.location_id,'file_location_hold',h.id,h.hold_kind,h.expires_at FROM file_location_holds h JOIN file_locations l ON l.id=h.location_id JOIN file_shadow_namespace_evidence e ON e.storage_profile_id=l.storage_profile_id AND e.object_key=l.object_key WHERE h.released_at IS NULL AND(h.expires_at IS NULL OR julianday(h.expires_at)>julianday('now'))
UNION ALL SELECT m.store_kind,m.provider,m.object_key,NULL,'file',h.file_id,'file_hold',h.id,h.hold_kind,h.expires_at FROM file_holds h JOIN legacy_file_mappings m ON m.file_id=h.file_id WHERE h.released_at IS NULL AND(h.expires_at IS NULL OR julianday(h.expires_at)>julianday('now'))
UNION ALL SELECT e.store_kind,e.provider,e.object_key,NULL,'file_shadow_occurrence',h.occurrence_id,'file_shadow_publication',h.occurrence_id,'shadow_publication',NULL FROM file_shadow_heads h JOIN file_shadow_decisions d ON d.occurrence_id=h.occurrence_id JOIN file_publications p ON p.file_id=d.file_id AND p.state='ready' JOIN file_locations l ON l.id=p.active_location_id JOIN file_shadow_namespace_evidence e ON e.storage_profile_id=l.storage_profile_id AND e.object_key=l.object_key WHERE h.present=1 AND d.decision='resolved';
CREATE VIEW blob_retention_edges AS SELECT * FROM blob_retention_edges_legacy_v14 UNION ALL SELECT * FROM file_shadow_legacy_retention_edges;

CREATE TRIGGER file_shadow_legacy_gc_insert_guard BEFORE INSERT ON blob_gc_ledger BEGIN SELECT RAISE(ABORT,'Shadow retention fences legacy deletion') WHERE NEW.state IN('deleting','deleted') AND EXISTS(SELECT 1 FROM file_shadow_legacy_retention_edges h WHERE h.store_kind=NEW.store_kind AND h.provider=NEW.provider AND h.object_key=NEW.object_key); END;

CREATE TRIGGER file_shadow_legacy_gc_update_guard BEFORE UPDATE ON blob_gc_ledger BEGIN SELECT RAISE(ABORT,'Shadow retention fences legacy deletion') WHERE NEW.state IN('deleting','deleted') AND EXISTS(SELECT 1 FROM file_shadow_legacy_retention_edges h WHERE h.store_kind=NEW.store_kind AND h.provider=NEW.provider AND h.object_key=NEW.object_key); END;

CREATE TRIGGER file_shadow_legacy_deletion_claims_admission_guard BEFORE INSERT ON file_shadow_legacy_deletion_claims BEGIN SELECT RAISE(ABORT,'Legacy deletion tombstone must capture a real terminal claim') WHERE NOT EXISTS(SELECT 1 FROM blob_gc_ledger g WHERE g.store_kind=NEW.store_kind AND g.provider=NEW.provider AND g.object_key=NEW.object_key AND g.state=NEW.first_state AND g.state IN('deleting','deleted') AND g.operation_id IS NEW.operation_id AND g.updated_at IS NEW.observed_at); END;

CREATE TRIGGER file_shadow_legacy_gc_insert_remember AFTER INSERT ON blob_gc_ledger WHEN NEW.state IN('deleting','deleted') BEGIN INSERT INTO file_shadow_legacy_deletion_claims(store_kind,provider,object_key,first_state,operation_id,observed_at) SELECT NEW.store_kind,NEW.provider,NEW.object_key,NEW.state,NEW.operation_id,NEW.updated_at WHERE NOT EXISTS(SELECT 1 FROM file_shadow_legacy_deletion_claims g WHERE g.store_kind=NEW.store_kind AND g.provider=NEW.provider AND g.object_key=NEW.object_key); END;

CREATE TRIGGER file_shadow_legacy_gc_update_remember AFTER UPDATE ON blob_gc_ledger WHEN NEW.state IN('deleting','deleted') BEGIN INSERT INTO file_shadow_legacy_deletion_claims(store_kind,provider,object_key,first_state,operation_id,observed_at) SELECT NEW.store_kind,NEW.provider,NEW.object_key,NEW.state,NEW.operation_id,NEW.updated_at WHERE NOT EXISTS(SELECT 1 FROM file_shadow_legacy_deletion_claims g WHERE g.store_kind=NEW.store_kind AND g.provider=NEW.provider AND g.object_key=NEW.object_key); END;

CREATE TRIGGER file_shadow_legacy_gc_revival_guard AFTER INSERT ON blob_gc_ledger WHEN NEW.state='orphaned' AND EXISTS(SELECT 1 FROM file_shadow_legacy_deletion_claims g WHERE g.store_kind=NEW.store_kind AND g.provider=NEW.provider AND g.object_key=NEW.object_key) BEGIN SELECT RAISE(ABORT,'Claimed legacy deletion cannot be replaced or revived'); END;

CREATE TRIGGER file_shadow_legacy_gc_terminal_update_guard BEFORE UPDATE ON blob_gc_ledger BEGIN SELECT RAISE(ABORT,'Claimed legacy deletion cannot be reopened by shadow conversion') WHERE OLD.state IN('deleting','deleted') AND (NEW.state NOT IN('deleting','deleted') OR NEW.store_kind IS NOT OLD.store_kind OR NEW.provider IS NOT OLD.provider OR NEW.object_key IS NOT OLD.object_key); END;

CREATE TRIGGER file_shadow_legacy_gc_terminal_delete_guard BEFORE DELETE ON blob_gc_ledger BEGIN SELECT RAISE(ABORT,'Claimed legacy deletion cannot be erased') WHERE OLD.state IN('deleting','deleted'); END;

CREATE TRIGGER file_shadow_legacy_gc_terminal_replace_guard BEFORE INSERT ON blob_gc_ledger BEGIN SELECT RAISE(ABORT,'Claimed legacy deletion cannot be replaced') WHERE EXISTS(SELECT 1 FROM blob_gc_ledger g WHERE ((NEW.state<>'orphaned' AND g.store_kind=NEW.store_kind AND g.provider=NEW.provider AND g.object_key=NEW.object_key) OR (NEW.rowid<>-1 AND g.rowid=NEW.rowid)) AND g.state IN('deleting','deleted')); END;

CREATE TRIGGER file_shadow_location_hold_legacy_guard BEFORE INSERT ON file_location_holds BEGIN SELECT RAISE(ABORT,'Location hold cannot cross legacy deletion') WHERE EXISTS(SELECT 1 FROM file_locations l JOIN legacy_file_mappings m ON m.location_id=l.id JOIN file_shadow_legacy_deletion_claims g ON g.store_kind=m.store_kind AND g.provider=m.provider AND g.object_key=m.object_key WHERE l.id=NEW.location_id); END;

CREATE TRIGGER file_shadow_file_hold_legacy_guard BEFORE INSERT ON file_holds BEGIN SELECT RAISE(ABORT,'File hold cannot cross legacy deletion') WHERE EXISTS(SELECT 1 FROM legacy_file_mappings m JOIN file_shadow_legacy_deletion_claims g ON g.store_kind=m.store_kind AND g.provider=m.provider AND g.object_key=m.object_key WHERE m.file_id=NEW.file_id); END;

CREATE TRIGGER file_shadow_location_gc_insert_source_hold_guard BEFORE INSERT ON file_location_gc_ledger BEGIN SELECT RAISE(ABORT,'Shadow source hold fences location deletion') WHERE NEW.state IN('deleting','deleted') AND EXISTS(SELECT 1 FROM file_locations l JOIN file_shadow_legacy_holds h ON h.storage_profile_id=l.storage_profile_id AND h.object_key=l.object_key WHERE l.id=NEW.location_id AND h.released_at IS NULL); END;

CREATE TRIGGER file_shadow_location_gc_update_source_hold_guard BEFORE UPDATE ON file_location_gc_ledger BEGIN SELECT RAISE(ABORT,'Shadow source hold fences location deletion') WHERE NEW.state IN('deleting','deleted') AND EXISTS(SELECT 1 FROM file_locations l JOIN file_shadow_legacy_holds h ON h.storage_profile_id=l.storage_profile_id AND h.object_key=l.object_key WHERE l.id=NEW.location_id AND h.released_at IS NULL); END;

CREATE TRIGGER file_shadow_generation_complete BEFORE DELETE ON file_shadow_runtime_guard BEGIN SELECT RAISE(ABORT,'V15 shadow runtime local gate cannot be deleted'); END;
